verus! {
    fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> (result: Vec<char>)
        ensures
            // 1) result.len() ≤ length of each input
            result.len() <= str1.len(),
            result.len() <= str2.len(),
            // 2) every character in result matches both inputs
            forall |i: int|
                0 <= i && (i as usize) < result.len() ==>
                    result[i as usize] == str1[i as usize]
                    && result[i as usize] == str2[i as usize],
            // 3) maximality: either we ran out of one input, or the next chars differ
            result.len() == str1.len()
                || result.len() == str2.len()
                || (   result.len() < str1.len()
                    && result.len() < str2.len()
                    && str1[result.len()] != str2[result.len()]),
    {
        let mut result: Vec<char> = Vec::new();
        let mut i: usize = 0;
        // Loop as long as we are within both inputs and characters agree
        while i < str1.len() && i < str2.len() && str1[i] == str2[i]
            invariant
                // bound on i
                i <= str1.len(),
                i <= str2.len(),
                // result has length i and matches up to i
                result.len() == i,
                forall |j: int|
                    0 <= j && (j as usize) < i ==>
                        result[j as usize] == str1[j as usize]
                        && result[j as usize] == str2[j as usize],
            decreases str1.len() - i,
        {
            result.push(str1[i]);
            i += 1;
        }

        // Upon exit, either i == str1.len() or i == str2.len() or str1[i] != str2[i],
        // so the maximality clause holds automatically.

        result
    }
}

